<template>
 <div class="provider-directory-shell" :class="{ 'latinx-directory': isLatinx }">
  <header class="directory-header"><RouterLink :to="base" class="brand" :aria-label="portal?.name || 'Provider directory'"><LatinxBrandArtwork v-if="isLatinx" class="brand-logo" kind="logo" label="Latinx Therapist Project CO" /><template v-else><span class="brand-mark" aria-hidden="true">✦</span><span>{{ portal?.name || 'Provider directory' }}<small>People. Culture. Connection.</small></span></template></RouterLink>
   <nav aria-label="Directory"><RouterLink :to="base">Find a provider</RouterLink><a v-if="portal?.website" :href="portal.website" target="_blank" rel="noopener">About the project ↗</a><RouterLink v-if="member" :to="`${base}/dashboard`">{{ member.role==='admin'?'Review dashboard':'My dashboard' }}</RouterLink></nav>
   <div class="header-actions"><div v-if="!member" class="login-wrap"><button type="button" :aria-expanded="loginOpen" @click="loginOpen=!loginOpen">Log in ▾</button><form v-if="loginOpen" class="login-panel" @submit.prevent="login"><h3>Directory login</h3><label>Username or email<input v-model="credentials.username" autocomplete="username" required /></label><label>Password<input v-model="credentials.password" type="password" autocomplete="current-password" required /></label><button class="primary" :disabled="busy">Log in</button><button type="button" @click="recoverOpen=true;loginOpen=false">Forgot password?</button></form></div><button v-else type="button" @click="logout">Log out</button>
    <div class="join-share" @mouseenter="joinHover=true" @mouseleave="joinHover=false" @focusin="joinHover=true" @focusout="joinHover=false"><RouterLink class="button primary" :to="`${base}/join`">New provider →</RouterLink><DirectoryShare v-if="portal" :url="portal.url" :name="portal.name" :directory-slug="portal.slug" :external-open="joinHover" default-target="join" /></div>
   </div>
  </header>
  <section class="directory-hero"><div class="hero-copy"><p class="eyebrow">{{ section==='join'?'Join our community':section==='dashboard'?'Your provider portal':'Mental health. Our communities. Stronger together.' }}</p><h1>{{ section==='join'?'Create your provider profile':section==='dashboard'?(member?.role==='admin'?'Directory review dashboard':'Your profile, your story'):'Find care that understands you.' }}</h1><p>{{ section==='join'?'Tell us about your practice, preview your listing and submit it for review.':section==='dashboard'?'Keep your information current and manage your place in the directory.':'Connect with culturally responsive providers across the United States. Search by state, language, specialty and how you want to meet.' }}</p></div><div v-if="isLatinx" class="latinx-hero-art" aria-hidden="true"><LatinxBrandArtwork kind="accent" /><LatinxBrandArtwork kind="leaves" /></div><div v-else class="hero-art" aria-hidden="true"><span>Tu historia.<br>Tu comunidad.<br>Tu bienestar.</span><i></i><b>✦</b></div></section>
  <main>
   <p v-if="error" class="alert error" role="alert">{{ error }}</p><p v-if="notice" class="alert" role="status">{{ notice }}</p><p v-if="loading" role="status">Loading directory…</p>
   <section v-if="resetToken" class="account-card"><h2>Set a new password</h2><form @submit.prevent="resetPassword"><label>New password (at least 12 characters)<input v-model="newPassword" type="password" minlength="12" autocomplete="new-password" required /></label><button class="primary" :disabled="busy">Update password</button></form></section>
   <section v-else-if="recoverOpen" class="account-card"><h2>Recover your directory account</h2><form @submit.prevent="recover"><label>Account email<input v-model="recoveryEmail" type="email" autocomplete="email" required /></label><button class="primary" :disabled="busy">Send reset link</button><button type="button" @click="recoverOpen=false">Back</button></form></section>
   <template v-else-if="portal && !loading">
    <template v-if="section==='join'">
     <section v-if="!member" class="account-card"><p class="eyebrow">Start your profile</p><h2>A place for your experience.</h2><p>Create a directory account to save your progress. Your profile will be reviewed before it goes live.</p><form @submit.prevent="register"><label>Account email (private)<input v-model="signup.email" type="email" autocomplete="email" required /></label><label>Choose a username<input v-model="signup.username" autocomplete="username" pattern="[a-zA-Z0-9._\-]{3,60}" required /></label><label>Create a password<input v-model="signup.password" type="password" minlength="12" autocomplete="new-password" required /></label><small>At least 12 characters; maximum 72 bytes.</small><button class="primary" :disabled="busy">{{ busy?'Creating account…':'Create account & build profile →' }}</button></form><p>Already started? <button type="button" @click="loginOpen=true">Log in to continue</button></p></section>
     <DirectoryWizard v-else-if="member.role==='provider'" :member="member" :portal="portal" @saved="member=$event" @submitted="submitted" @refresh="refreshMember" />
     <p v-else>Use a separate provider account to create a listing. <RouterLink :to="`${base}/dashboard`">Open your review dashboard</RouterLink></p>
    </template>
    <template v-else-if="section==='dashboard'">
     <section v-if="!member" class="account-card"><h2>Welcome back</h2><p>Log in to manage your directory profile.</p><button class="primary" @click="loginOpen=true">Open login</button></section>
     <template v-else-if="member.role==='admin'"><div class="dashboard-top"><div><h2>Provider submissions</h2><p>{{ reviews.filter(m=>m.status==='pending').length }} awaiting review · {{ reviews.length }} provider accounts</p></div><button @click="loadReviews">Refresh submissions</button></div>
      <p class="alert">Review credentials, public contact details and the profile before approval. Approval publishes the submitted version shown here.</p>
      <label class="review-filter">Show<select v-model="reviewFilter"><option value="">All profiles</option><option v-for="s in ['pending','approved','draft','changes_requested','rejected','suspended']" :key="s" :value="s">{{ statusLabel(s) }}</option></select></label>
      <div v-if="!filteredReviews.length" class="empty"><h3>No profiles here yet</h3><p>Share the new provider enrollment link to invite submissions.</p><DirectoryShare :url="portal.url" :name="portal.name" :directory-slug="portal.slug" /></div>
      <div class="review-list"><button v-for="m in filteredReviews" :key="m.id" class="review-row" @click="reviewing=m;reviewNote=m.reviewNote"><span><strong>{{ m.profile.name || m.username }}</strong><small>{{ m.email }}</small></span><span class="status">{{ statusLabel(m.status) }}</span><span>Review →</span></button></div>
     </template>
     <template v-else><div class="dashboard-grid"><section class="dashboard-card"><p class="eyebrow">Directory status</p><h2>{{ member.published?'Your approved profile is live':statusLabel(member.status) }}</h2><p>{{ member.published && member.status!=='approved'?'Your last approved profile remains live. Submit your latest changes for review.':member.status==='pending'?'The directory team is reviewing your submission.':'Complete your profile and send it to the directory team.' }}</p><p v-if="member.reviewNote" class="alert">{{ member.reviewNote }}</p><RouterLink class="button primary" :to="`${base}/join`">{{ member.status==='draft'?'Continue your profile':'Edit profile' }} →</RouterLink><button v-if="member.optIn" class="withdraw" :disabled="busy" @click="withdraw">Withdraw from directory</button><p v-if="!member.verified">Email not verified. <button :disabled="busy" @click="resend">Resend verification</button><button @click="refreshMember">Refresh verification</button></p></section><section><h3>Your latest saved profile</h3><DirectoryProfile :profile="member.profile" @open="selected=member.profile" /></section></div></template>
     <section v-if="member" class="dashboard-card account-security"><h3>Directory password</h3><p>Use this username with your directory password: <strong>{{ member.username }}</strong></p><form @submit.prevent="changePassword"><label>Current password (leave blank when setting your first directory password)<input v-model="currentPassword" type="password" autocomplete="current-password" /></label><label>New password<input v-model="newPassword" type="password" autocomplete="new-password" minlength="12" required /></label><button :disabled="busy">Save directory password</button></form></section>
    </template>
    <template v-else>
     <form class="search-bar" @submit.prevent="search(1)"><label>Name, city or ZIP<input v-model="filters.search" type="search" placeholder="Where do you need care?" /></label><label>State / territory<select v-model="filters.state"><option value="">Any state</option><option v-for="s in STATES" :key="s">{{ s }}</option></select></label><label>Care type<select v-model="filters.care"><option value="">Any care type</option><option value="virtual">Virtual</option><option value="inPerson">In person</option></select></label><button class="primary" :disabled="busy">Search providers →</button></form>
     <div class="finder-layout"><aside class="filter-panel"><h3>Refine your search</h3><label>Language<select v-model="filters.language" @change="search(1)"><option value="">Any language</option><option v-for="s in LANGUAGES" :key="s">{{ s }}</option></select></label><label>Insurance / payment<select v-model="filters.insurance" @change="search(1)"><option value="">Any payment option</option><option v-for="s in INSURANCES" :key="s">{{ s }}</option></select></label><label>Specialty<select v-model="filters.specialty" @change="search(1)"><option value="">Any specialty</option><option v-for="s in SPECIALTIES" :key="s">{{ s }}</option></select></label><label>Client ages<select v-model="filters.age" @change="search(1)"><option value="">Any age</option><option v-for="s in CLIENT_AGES" :key="s">{{ s }}</option></select></label><button @click="clearFilters">Clear filters</button></aside>
      <section><p class="results-count" aria-live="polite">{{ total }} {{ total===1?'provider':'providers' }} found</p><div v-if="providers.length" class="provider-grid"><DirectoryProfile v-for="p in providers" :key="p.id" :profile="p" @open="selected=$event" /></div><div v-else class="empty"><span aria-hidden="true">✦</span><h2>{{ activeFilters?'No providers match these filters yet.':'Our directory is growing.' }}</h2><p>{{ activeFilters?'Try another state or broaden your search.':'Providers will appear here after their profiles are approved. Help build a community of culturally responsive care.' }}</p><RouterLink class="button primary" :to="`${base}/join`">New provider →</RouterLink></div><div v-if="total>24" class="pagination"><button :disabled="page<=1||busy" @click="search(page-1)">Previous</button><span>Page {{ page }} of {{ Math.ceil(total/24) }}</span><button :disabled="page*24>=total||busy" @click="search(page+1)">Next</button></div></section>
     </div>
     <section class="community-banner"><LatinxBrandArtwork v-if="isLatinx" kind="leaves" class="community-leaves" /><div><p class="eyebrow">More than a directory</p><h2>Connection begins with understanding.</h2><p>A place to discover providers who bring culture, language and lived experience to their work.</p></div><DirectoryShare :url="portal.url" :name="portal.name" :directory-slug="portal.slug" /></section>
    </template>
   </template>
  </main>
  <footer><LatinxBrandArtwork v-if="isLatinx" kind="logo" class="footer-logo" label="Latinx Therapist Project CO" /><strong>{{ portal?.name || 'Provider directory' }}</strong><span>A nationwide community of care.</span><a v-if="portal?.website" :href="portal.website" target="_blank" rel="noopener">Visit the project website ↗</a></footer>
  <dialog ref="profileDialog" @click="closeBackdrop" @close="selected=null;reviewing=null"><button class="dialog-close" aria-label="Close profile" @click="closeDialog">✕</button><template v-if="reviewing"><h2>Review {{ reviewing.profile.name || reviewing.username }}</h2><p><strong>Account:</strong> {{ reviewing.email }} · {{ reviewing.verified?'Email verified':'Email not verified' }}</p><p><strong>Heritage (private):</strong> {{ reviewing.heritage || 'Not provided' }} · {{ reviewing.optIn?'Consented to publication':'No publication consent' }}</p><h3>Credentials for review (private)</h3><ul><li v-for="(l,i) in reviewing.profile.licenses" :key="i">{{ l.state }} · {{ l.type }} · {{ l.number }} · expires {{ l.expires }}</li></ul><DirectoryProfile :profile="reviewing.profile" detail /><label>Feedback to provider<textarea v-model="reviewNote" rows="3" maxlength="4000" /></label><p v-if="reviewError" class="error" role="alert">{{ reviewError }}</p><div class="review-actions"><button v-if="reviewing.status==='pending'" class="primary" :disabled="busy" @click="review('approved')">Approve & publish</button><button :disabled="busy" @click="review('changes_requested')">Request changes</button><button :disabled="busy" @click="review('rejected')">Decline</button><button :disabled="busy" @click="review('suspended')">Suspend listing</button></div></template><DirectoryProfile v-else-if="selected" :profile="selected" detail /></dialog>
 </div>
</template>
<script setup>
import {ref,computed,watch,onMounted,nextTick} from 'vue';import {useRoute,useRouter} from 'vue-router';
import {directoryRequest,rememberSession,sessionToken,STATES,LANGUAGES,INSURANCES} from '../../services/providerDirectory';
import {SPECIALTIES,CLIENT_AGES} from '../../constants/providerClinicalTaxonomy';
import LatinxBrandArtwork from '../../components/providerDirectory/LatinxBrandArtwork.vue';
import DirectoryProfile from '../../components/providerDirectory/DirectoryProfile.vue';import DirectoryWizard from '../../components/providerDirectory/DirectoryWizard.vue';import DirectoryShare from '../../components/providerDirectory/DirectoryShare.vue';
const route=useRoute(),router=useRouter();const slug=computed(()=>String(route.params.directorySlug||'latinx')),base=computed(()=>slug.value==='latinx'?'/latinx':`/provider-directory/${slug.value}`),section=computed(()=>route.params.section||'');
const isLatinx=computed(()=>slug.value==='latinx');
const joinHover=ref(false);
const portal=ref(null),member=ref(null),loading=ref(true),busy=ref(false),error=ref(''),notice=ref(''),loginOpen=ref(false),recoverOpen=ref(false),recoveryEmail=ref(''),resetToken=ref(''),newPassword=ref(''),currentPassword=ref('');
const credentials=ref({username:'',password:''}),signup=ref({email:'',username:'',password:''});
const providers=ref([]),total=ref(0),page=ref(1),filters=ref({search:'',state:'',care:'',language:'',insurance:'',specialty:'',age:''});const activeFilters=computed(()=>Object.values(filters.value).some(Boolean));
const selected=ref(null),profileDialog=ref(null),reviews=ref([]),reviewing=ref(null),reviewNote=ref(''),reviewError=ref(''),reviewFilter=ref('pending');
const filteredReviews=computed(()=>reviews.value.filter(m=>!reviewFilter.value||m.status===reviewFilter.value));
const statusLabel=s=>({draft:'Profile in progress',pending:'Waiting for review',approved:'Approved',changes_requested:'Changes requested',rejected:'Not approved',suspended:'Listing suspended'}[s]||s);
async function action(fn){busy.value=true;error.value='';try{return await fn();}catch(e){error.value=e.response?.data?.error?.message||'We could not complete this request. Please try again.';}finally{busy.value=false;}}
function acceptSession(data){rememberSession(slug.value,data.token);member.value=data.member;}
async function search(p=1){await action(async()=>{const query=new URLSearchParams({...filters.value,page:p});const data=await directoryRequest(slug.value,`/providers?${query}`);providers.value=data.providers;total.value=data.total;page.value=p;});}
function clearFilters(){Object.keys(filters.value).forEach(k=>filters.value[k]='');search(1);}
async function register(){await action(async()=>{const data=await directoryRequest(slug.value,'/register','post',signup.value);acceptSession(data);signup.value.password='';notice.value=data.notice;});}
async function login(){await action(async()=>{acceptSession(await directoryRequest(slug.value,'/login','post',credentials.value));credentials.value.password='';loginOpen.value=false;router.push(`${base.value}/dashboard`);await loadReviews();});}
async function logout(){await action(async()=>{await directoryRequest(slug.value,'/me/logout','post',{});rememberSession(slug.value,'');member.value=null;reviews.value=[];router.push(base.value);await search();});}
async function refreshMember(){await action(async()=>member.value=await directoryRequest(slug.value,'/me'));}
async function submitted(m){member.value=m;notice.value='Your profile was submitted. The directory team will review it before publication.';router.push(`${base.value}/dashboard`);}
async function withdraw(){await action(async()=>{member.value=await directoryRequest(slug.value,'/me','put',{profile:member.value.profile,heritage:member.value.heritage,optIn:false,revision:member.value.revision});notice.value='Your profile has been removed from the public directory.';});}
async function resend(){await action(async()=>notice.value=(await directoryRequest(slug.value,'/me/verify','post',{})).message);}
async function recover(){await action(async()=>notice.value=(await directoryRequest(slug.value,'/recover','post',{email:recoveryEmail.value})).message);}
async function resetPassword(){await action(async()=>{notice.value=(await directoryRequest(slug.value,'/token','post',{token:resetToken.value,purpose:'reset',password:newPassword.value})).message;resetToken.value='';newPassword.value='';rememberSession(slug.value,'');member.value=null;loginOpen.value=true;});}
async function changePassword(){await action(async()=>{acceptSession(await directoryRequest(slug.value,'/me/password','put',{currentPassword:currentPassword.value,password:newPassword.value}));currentPassword.value='';newPassword.value='';notice.value='Your directory password has been saved.';});}
async function loadReviews(){if(member.value?.role==='admin') await action(async()=>reviews.value=await directoryRequest(slug.value,'/review'));}
async function review(decision){busy.value=true;reviewError.value='';try{await directoryRequest(slug.value,`/review/${reviewing.value.id}`,'post',{action:decision,note:reviewNote.value,revision:reviewing.value.revision});closeDialog();await loadReviews();notice.value='Review decision saved.';}catch(e){reviewError.value=e.response?.data?.error?.message||'Review could not be saved.';}finally{busy.value=false;}}
function closeDialog(){profileDialog.value?.close();selected.value=null;reviewing.value=null;reviewError.value='';}
function closeBackdrop(e){if(e.target===profileDialog.value){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog();}}
watch([selected,reviewing],async([p,m])=>{if(p||m){await nextTick();profileDialog.value?.showModal();}});
watch(section,()=>{error.value='';if(section.value==='dashboard')loadReviews();else if(!section.value)search();});
async function initialize(){loading.value=true;portal.value=null;member.value=null;providers.value=[];reviews.value=[];closeDialog();await action(async()=>{portal.value=await directoryRequest(slug.value);if(sessionToken(slug.value)){try{member.value=await directoryRequest(slug.value,'/me');}catch(e){if(e.response?.status===401)rememberSession(slug.value,'');else throw e;}}
 const token=route.query.verify||route.query.reset;if(token){const purpose=route.query.verify?'verify':'reset';await router.replace({path:route.path,query:{}});if(purpose==='reset')resetToken.value=String(token);else{notice.value=(await directoryRequest(slug.value,'/token','post',{purpose,token})).message;if(member.value)member.value=await directoryRequest(slug.value,'/me');}}
 });loading.value=false;if(section.value==='dashboard')await loadReviews();else if(!section.value)await search();}
onMounted(initialize);
watch(slug,initialize);
</script>
<style scoped>
.provider-directory-shell{--purple:#631957;--ink:#302337;background:#fbfaf8;color:var(--ink);min-height:100vh;font-family:Inter,system-ui,-apple-system,sans-serif;font-size:15px}.provider-directory-shell :deep(*){box-sizing:border-box}.provider-directory-shell :deep(button),.button{border:1px solid #d9c9df;background:#fff;color:var(--purple);padding:11px 16px;border-radius:9px;font:600 14px inherit;cursor:pointer;text-decoration:none;display:inline-flex;align-items:center;justify-content:center;gap:8px}.provider-directory-shell :deep(button:disabled){opacity:.5;cursor:not-allowed}.provider-directory-shell :deep(.primary){background:var(--purple);color:white;border-color:var(--purple)}.provider-directory-shell :deep(input:not([type=checkbox])),.provider-directory-shell :deep(select),.provider-directory-shell :deep(textarea){width:100%;background:white;color:var(--ink);border:1px solid #d8cddd;border-radius:8px;padding:12px;font:inherit;min-width:0}.provider-directory-shell :deep(input[type=checkbox]){accent-color:var(--purple)}.provider-directory-shell :deep(label){font-size:14px}.provider-directory-shell :deep(:focus-visible){outline:3px solid #c392d6;outline-offset:3px}.directory-header{background:white;padding:20px max(24px,calc((100vw - 1440px)/2));display:flex;align-items:center;gap:28px;position:relative;z-index:40;border-bottom:1px solid #eee}.brand{color:var(--purple);font-weight:800;display:flex;gap:10px;text-decoration:none;max-width:280px;line-height:1.2}.brand-mark{font-size:40px;color:#e1a83b}.brand small{display:block;font-size:10px;text-transform:uppercase;letter-spacing:.12em;margin-top:7px}.directory-header nav{display:flex;align-items:center;gap:24px;flex:1;font-size:13px}.directory-header nav a{color:var(--ink);text-decoration:none}.header-actions{display:flex;align-items:center;gap:12px}.join-share{display:flex;gap:8px;align-items:center}.login-wrap{position:relative}.login-panel{position:absolute;right:0;top:calc(100% + 10px);width:300px;backgrou